/*
* Cheat Engine Detection Using Signature scan
* This project detects Cheat Engine via signature scanning.
* This detection scans the process icon, which is often overlooked in bypass attempts.
* Pros: Fast and reliable; scans a consistent location, minimizing performance impact.
* Cons: May fail due to privilege issues; requires equal or higher privileges than Cheat Engine.
* Note: This check should not result in false positives, as it only scans the process's own icon.
* For questions, contact "0Hikarix" on x.
*/



HICON GetProcessIcon(DWORD processId) {
    HICON hIcon = NULL;
    /*
    * This section obtains a handle to the scanned process.
    * It's important to note that acquiring process handles may be restricted for certain system processes
    * that have higher privileges than our program.
    * Even if our program is running with administrator privileges, it may still fail to obtain handles
    * for processes with elevated privileges, requiring kernel-level access.
    * However, for our purpose of detecting Cheat Engine, which typically runs without system-level privileges,
    * this should not pose an issue.
    */

    HANDLE hProcess = OpenProcess(PROCESS_QUERY_INFORMATION | PROCESS_VM_READ, FALSE, processId);
    if (hProcess == NULL) {
        // the two lines below are for debug. if the detection isn't working this should tell why what it's scanning and why it's failing
        // std::cout << "cheat engine openprocess failed\n";
        // std::cout << processId << '\n';
        //std::this_thread::sleep_for(std::chrono::milliseconds(3));
    }
    if (hProcess != NULL) {
        HMODULE hModules[1024];
        DWORD cbNeeded;
        if (EnumProcessModules(hProcess, hModules, sizeof(hModules), &cbNeeded)) {
            for (DWORD i = 0; i < (cbNeeded / sizeof(HMODULE)); i++) {
                TCHAR szModule[MAX_PATH];
                if (GetModuleFileNameEx(hProcess, hModules[i], szModule, sizeof(szModule) / sizeof(TCHAR))) {
                    hIcon = ExtractIcon(NULL, szModule, 0);
                    if (hIcon != NULL) {
                        break;
                    }
                }
            }
        }
        CloseHandle(hProcess);
    }
    return hIcon;
}


std::vector<BYTE> BitmapToBytes(HBITMAP hBitmap) {
    BITMAP bmp = { 0 };
    std::vector<BYTE> bytes;

    if (GetObject(hBitmap, sizeof(BITMAP), &bmp)) {
        DWORD bufferSize = bmp.bmWidthBytes * bmp.bmHeight;
        bytes.resize(bufferSize);

        if (GetBitmapBits(hBitmap, bufferSize, bytes.data()) == 0) {
            // Handle the case if GetIconInfo failed
            std::cout << "GetbitmapBits Failed\n";
            bytes.clear();
        }
    }

    return bytes;
}


std::vector<BYTE> IconToBytes(HICON hIcon) {
    std::vector<BYTE> bytes;

    ICONINFO iconInfo;
    if (GetIconInfo(hIcon, &iconInfo)) {
        if (iconInfo.hbmColor != NULL) {
            bytes = BitmapToBytes(iconInfo.hbmColor);
            DeleteObject(iconInfo.hbmColor);
        }
        else {
            // Handle the case when hbmColor is NULL (e.g., monochrome icon)
            std::cout << "hbmColor is NULL\n";
        }
        // Always delete hbmMask, regardless of hbmColor's status
        if (iconInfo.hbmMask != NULL) {
            DeleteObject(iconInfo.hbmMask);
        }
    }
    else {
        // Handle the case when GetIconInfo is NULL
        std::cout << "GetIconInfo failed\n";
    }


    return bytes;
}

